/* WHEEL */
const pol=(r,a)=>{const t=(a-90)*Math.PI/180;return[350+r*Math.cos(t),350+r*Math.sin(t)]};
const sec=(r0,r1,a0,a1)=>{const A=pol(r1,a0),B=pol(r1,a1),C=pol(r0,a1),E=pol(r0,a0),l=a1-a0>180?1:0;return`M${A}A${r1} ${r1} 0 ${l} 1 ${B}L${C}A${r0} ${r0} 0 ${l} 0 ${E}Z`};
function sg(r0,r1,a0,a1,h,l,t,fs,cl,ev){const m=(a0+a1)/2,[x,y]=pol((r0+r1)/2,m),rot=m>180?m+90:m-90;
 return`<g class="sg ${cl}" ${ev} tabindex="0" role="button" aria-label="${t}" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();this.dispatchEvent(new MouseEvent('click'))}" onfocus="${ev.match(/onmouseover="([^"]*)"/)[1]}"><path d="${sec(r0,r1,a0,a1)}" fill="hsl(${h} 38% ${l-4}%)" stroke="#fff8f1" stroke-width="2"/><text x="${x}" y="${y}" transform="rotate(${rot} ${x} ${y})" text-anchor="middle" dominant-baseline="central" font-size="${fs}">${t}</text></g>`}
function wheel(){const W=S.W;let h=`<svg viewBox="0 0 700 700" style="width:100%;max-width:640px;display:block;margin:auto" role="img" aria-label="Interactive feelings wheel">`;
 D.forEach((c,ci)=>{const a0=ci*60,dim=W.c>=0&&W.c!=ci?"dm":"";
  h+=sg(70,150,a0,a0+60,c.h,78,c.n,15,(W.c==ci&&W.s<0?"sl ":"")+dim,`onclick="pk(${ci},-1,-1)" onmouseover="hv(${ci},-1,-1)"`);
  const w=60/c.s.length;c.s.forEach((s,si)=>{const b=a0+si*w;
   h+=sg(150,250,b,b+w,c.h,86,s.n,c.s.length>7?10.5:12,(W.c==ci&&W.s==si&&W.t<0?"sl ":"")+dim,`onclick="pk(${ci},${si},-1)" onmouseover="hv(${ci},${si},-1)"`);
   if(W.c==ci){const v=w/2;s.t.forEach((t,ti)=>{h+=sg(250,340,b+ti*v,b+ti*v+v,c.h,92,t,9.5,W.s==si&&W.t==ti?"sl":"",`onclick="pk(${ci},${si},${ti})" onmouseover="hv(${ci},${si},${ti})"`)})}})});
 h+=`<circle cx="350" cy="350" r="68" fill="#fff8f1"/><text x="350" y="344" text-anchor="middle" font-family="Manrope,sans-serif" font-weight="600" font-size="17" fill="#4f7a67">how do</text><text x="350" y="372" text-anchor="middle" font-family="Manrope,sans-serif" font-weight="600" font-size="17" fill="#4f7a67">you feel?</text></svg>`;$("#wh").innerHTML=h}
const nm=(c,s,t)=>t>=0?D[c].s[s].t[t]:s>=0?D[c].s[s].n:D[c].n;
const ds=(c,s,t)=>`You might be feeling ${nm(c,s,t).toLowerCase()}, part of the ${D[c].n.toLowerCase()} family. There’s no right or wrong here.`;
function hv(c,s,t){$("#inf").innerHTML=`<b>${EMO[c]} ${nm(c,s,t)}</b><br><span class="mut">${ds(c,s,t)}</span>`}
function pk(c,s,t){S.W={c,s,t,i:3};wheel();pn()}
function pn(){const W=S.W;if(W.c<0){$("#pn").innerHTML=`<p class="hand">Tap a colour in the centre, then move outward to get more specific.</p>`;return}const n=nm(W.c,W.s,W.t);
 $("#pn").innerHTML=`<h3>${EMO[W.c]} ${n}</h3><p>Is this what you're feeling?</p><p class="row n">${[1,2,3,4,5].map(i=>`<label><input type="radio" name="in" style="width:auto" ${i==W.i?"checked":""} onchange="S.W.i=${i}"> ${i}${i==1?" — Very low":i==3?" — Moderate":i==5?" — Very high":""}</label>`).join("")}</p><p><b>Want to explore this feeling?</b></p><div class="row n"><button class="b s" onclick="jn()">Journal about it</button><button class="b s a" onclick="trk()">Track this feeling</button><button class="b s a" onclick="ex()">Learn about it</button><button class="b s a" onclick="go('pros')">Find support</button></div><div class="c" style="margin-top:12px;background:var(--blush)"><b>Want to put this feeling into words?</b><br><button class="b s" style="margin-top:8px" onclick="jn()">Start a journal entry →</button></div><div id="ep"></div>`}
function trk(){const W=S.W;S.hist.unshift(["Today",nm(W.c,W.s,W.t),W.c,0,W.i]);bump();draw();pk(W.c,W.s,W.t);toast("Feeling tracked. Your emotional landscape is updated.")}
function ex(){const W=S.W;$("#ep").innerHTML=`<div class="c" style="margin-top:12px;background:var(--sage)"><b>Feeling: ${nm(W.c,W.s,W.t)}</b><p>${ds(W.c,W.s,W.t)}</p><b>You could try:</b><ul style="margin:6px 0;padding-left:20px"><li>Take a few slow breaths</li><li>Write what’s worrying you</li><li>Learn more about it in Explore</li><li>Consider talking to a professional</li></ul><p class="mut">These are gentle ideas, not treatments or a diagnosis.</p></div>`}
