function proList(){const f=S.f,L=PROS.map((p,i)=>[p,i]).filter(([p])=>(!f.q||(p[0]+p[1]+p[3].join()).toLowerCase().includes(f.q.toLowerCase()))&&(!f.t||p[1]==f.t)&&(!f.m||p[7]=="Both"||p[7]==f.m)&&(!f.l||p[4].includes(f.l)||(f.l=="Hinglish"&&p[4].includes("Hindi")))&&(!f.sp||(KW[f.sp]||[]).some(w=>p[3].join(" ").toLowerCase().includes(w)))&&(!f.g||p[8]==f.g)&&(!f.a||p[9]==f.a)&&p[6]<=(f.pr||9999)&&p[5]>=(f.x||0)&&(!f.st||(p[11]||"").includes(f.st)));
 $("#pl").innerHTML=L.map(([p,i])=>`<article class="pro"><div><h3>${p[0]}</h3><div class="mut">${p[1]} · ${p[2]}</div><p><b>${p[3].join(" • ")}</b></p><span class="tag y">Demo profile</span></div><div><p class="mut">₹${p[6]} / session · ${p[7]}<br>${p[4].join(" • ")}<br>Therapy style: <b>${p[11]}</b><br>${p[5]} years · ★ ${p[10]} (sample)</p></div><div><blockquote class="pq">“${PQ[i]}”</blockquote>${cn}<p class="row n"><button class="b" onclick="vp(${i})">Meet ${p[0].replace("Dr. ","").split(" ")[0]} →</button><button class="b a" onclick="bk(${i})">Book Session</button></p></div></article>`).join("")||CD+`<p class="mut">No match yet. Try loosening a filter.</p>`}
R.pros=()=>{setTimeout(proList);const so=(k,a,l)=>`<select aria-label="${l}" onchange="sf('${k}',this.value)">${op(a,l)}</select>`;return`<span class="ann">take your time.</span><h1>Finding help shouldn’t feel like another task.</h1><p class="lead">Find someone who fits your needs, preferences and comfort.</p><p><button class="b" onclick="go('match')">Take the 2-minute matching</button></p><div class="fl2"><input placeholder="Search by name, specialisation or concern" aria-label="Search" oninput="sf('q',this.value)"><div class="row">${so("t",["Psychologist","Psychiatrist","Counsellor","Therapist"],"Professional type")}${so("m",["Online","In-person"],"Mode")}${so("l",["English","Hindi","Hinglish","Bengali","Marathi","Tamil","Telugu","Gujarati","Punjabi","Other"],"Language")}${so("sp",Object.keys(KW),"Specialisation")}<select aria-label="Gender preference" onchange="sf('g',this.value)"><option value="">Gender preference</option><option value="F">Woman</option><option value="M">Man</option></select>${so("a",["Weekdays","Evenings","Weekends"],"Availability")}<select aria-label="Price" onchange="sf('pr',this.value)"><option value="">Any price</option><option value="800">Up to ₹800</option><option value="1200">Up to ₹1,200</option><option value="1500">Up to ₹1,500</option></select><select aria-label="Experience" onchange="sf('x',this.value)"><option value="">Any experience</option><option value="5">5+ years</option><option value="10">10+ years</option></select>${so("st",["Warm","Structured","Conversational","Direct","Gentle","Skills-focused","Creative","Trauma-informed"],"Therapy style")}</div></div><h2 style="margin-top:30px">Professionals</h2><div id="pl"></div>`};
function vp(i){const p=PROS[i];md(`<h2 style="margin:0">${p[0]}</h2><p class="mut">${p[1]} · ${p[2]} · ${p[5]} years</p><span class="tag y">Demo profile</span><span class="tag">Verification badge (demo)</span><blockquote class="pq">“${PQ[i]}”</blockquote><p>Focus: <b>${p[3].join(" • ")}</b><br>Languages: ${p[4].join(" • ")}<br>Therapy style: ${p[11]}<br>₹${p[6]} / session · ${p[7]}</p>${cn}<p class="row n"><button class="b" onclick="bk(${i})">Book Session</button><button class="b a" onclick="svp(${i})">${S.sv.includes(i)?"Saved":"Save professional"}</button><button class="b a" onclick="cm();go('prep')">Prepare for first session</button></p>`)}

